const NORMAL_TIMING = Object.freeze({ flip: 3_250, cut: 1_450 });
const REDUCED_TIMING = Object.freeze({ flip: 80, cut: 80 });
let active = null;
let openSeq = 0;

function _big(value) {
  try { return BigInt(value ?? 0); } catch (_e) { return 0n; }
}

function _rankLabel(value) {
  const rank = Number(value);
  return Number.isInteger(rank) && rank >= 1 && rank <= 4 ? `RANK #${rank}` : '';
}

function _formatEth(value, digits = 3) {
  try {
    const [whole, fraction] = displayEthCompact(_big(value), digits).split('.');
    const grouped = whole.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
    return fraction == null ? grouped : `${grouped}.${fraction}`;
  } catch (_e) { return '0'; }
}

function _formatDrawWeight(value) {
  const amount = _big(value);
  const units = [
    [1_000_000_000_000n, 'T'],
    [1_000_000_000n, 'B'],
    [1_000_000n, 'M'],
    [1_000n, 'K'],
  ];
  for (const [unit, suffix] of units) {
    if (amount < unit) continue;
    const tenths = (amount * 10n) / unit;
    return `${tenths / 10n}${tenths % 10n === 0n ? '' : `.${tenths % 10n}`}${suffix}`;
  }
  return amount.toLocaleString('en-US');
}

export function formatBafWhalePassHalves(value) {
  const halves = _big(value);
  if (halves > 0n && halves % 2n === 0n) {
    const passes = halves / 2n;
    return `${passes} WHALE PASS${passes === 1n ? '' : 'ES'}`;
  }
  return `${halves} HALF-PASS${halves === 1n ? '' : 'ES'}`;
}

function _motionReduced() {
  try { return matchMedia('(prefers-reduced-motion: reduce)').matches; }
  catch (_e) { return false; }
}

function _sound(fn) {
  try {
    const result = fn?.();
    if (result && typeof result.catch === 'function') result.catch(() => {});
  } catch (_e) { /* audio is enhancement only */ }
}

function _schedule(fn, ms) {
  if (!active) return null;
  const handle = setTimeout(() => {
    if (!active) return;
    active.timers.delete(handle);
    fn();
  }, ms);
  active.timers.add(handle);
  try { handle?.unref?.(); } catch (_e) { /* browser timer */ }
  return handle;
}

function _destroyActive() {
  const current = active;
  active = null;
  if (current) {
    for (const handle of current.timers) clearTimeout(handle);
    current.timers.clear();
    try { document.removeEventListener('keydown', current.onKeydown); } catch (_e) {}
    try { current.overlay.remove(); } catch (_e) {}
    try { current.previousFocus?.focus({ preventScroll: true }); } catch (_e) {}
  }
  // Always repair both handoff states, including an interrupted pre-mount load.
  try {
    document.body?.classList?.remove('baf-resolution-pending');
    document.body?.classList?.remove('baf-resolution-open');
  } catch (_e) {}
}

function _clearActive() {
  openSeq += 1;
  _destroyActive();
}

export function closeBafResolution() {
  _clearActive();
}

function _drawLegendRow({ kind, color, label, weight, percent }) {
  const row = document.createElement('li');
  row.dataset.kind = kind;
  const swatch = document.createElement('i');
  swatch.style.setProperty('--baf-draw-color', color);
  swatch.setAttribute('aria-hidden', 'true');
  const identity = document.createElement('span');
  identity.textContent = label;
  const score = document.createElement('b');
  score.textContent = weight;
  const share = document.createElement('strong');
  share.textContent = percent;
  row.appendChild(swatch);
  row.appendChild(identity);
  row.appendChild(score);
  row.appendChild(share);
  return row;
}

function _paintWeightedDraw(overlay, snapshot) {
  const draw = snapshot.draw;
  const allocation = buildBafDrawAllocation(draw, snapshot.player.address);
  const pie = overlay.querySelector('[data-bind="baf-draw-pie"]');
  const legend = overlay.querySelector('[data-bind="baf-draw-legend"]');
  const chance = overlay.querySelector('[data-bind="baf-draw-player-percent"]');
  const playerWeight = overlay.querySelector('[data-bind="baf-draw-player-weight"]');
  const context = overlay.querySelector('[data-bind="baf-draw-context"]');
  const state = overlay.querySelector('[data-bind="baf-draw-state"]');
  const total = _big(draw?.totalWeight);
  const ownWeight = _big(draw?.player?.score);
  const ownPercent = formatBafDrawPercent(ownWeight, draw?.totalWeight);

  if (chance) chance.textContent = ownPercent;
  if (playerWeight) {
    playerWeight.textContent = draw?.player
      ? `${_formatDrawWeight(ownWeight)} FLIP WEIGHT`
      : 'NO FINAL-DAY ENTRY';
  }
  if (context) {
    const playerCount = draw?.totalParticipants == null
      ? '— PLAYERS'
      : `${draw.totalParticipants.toLocaleString('en-US')} PLAYERS`;
    context.textContent = total <= 0n
      ? `FINAL-DAY BOOK UNAVAILABLE · ${playerCount}`
      : `${_formatDrawWeight(total)} FLIP IN THE BOOK · ${playerCount}`;
  }
  if (state) state.textContent = snapshot.gateWon ? 'WAITING FOR DRAW' : 'VOID · BAF LOSS';

  const visibleSlices = allocation.entries.filter((entry) => entry.endPpm > entry.startPpm);
  if (pie) {
    pie.classList.toggle('is-empty', visibleSlices.length === 0);
    if (visibleSlices.length > 0) {
      const stops = visibleSlices.flatMap((entry) => {
        const start = (entry.startPpm / 10_000).toFixed(4);
        const end = (entry.endPpm / 10_000).toFixed(4);
        return `${entry.color} ${start}% ${end}%`;
      });
      pie.style.setProperty('--baf-draw-pie', `conic-gradient(from -90deg, ${stops.join(', ')})`);
    } else {
      pie.style.removeProperty('--baf-draw-pie');
    }
    pie.setAttribute(
      'aria-label',
      `Final-day BAF draw weights. Your chance ${ownPercent}.`,
    );
  }

  if (!legend) return;
  legend.textContent = '';
  legend.appendChild(_drawLegendRow({
    kind: 'player',
    color: '#d9fff5',
    label: 'YOU',
    weight: draw?.player ? `${_formatDrawWeight(ownWeight)} FLIP` : 'NO ENTRY',
    percent: ownPercent,
  }));
  const fieldWeight = total > ownWeight ? total - ownWeight : 0n;
  legend.appendChild(_drawLegendRow({
    kind: 'field',
    color: '#334155',
    label: 'EVERYONE ELSE',
    weight: total > 0n ? `${_formatDrawWeight(fieldWeight)} FLIP` : '—',
    percent: formatBafDrawPercent(fieldWeight, draw?.totalWeight),
  }));
}


export const BAF_REVEAL_LAYOUTS = Object.freeze(['cards', 'lanes', 'ledger', 'bracket', 'tickets', 'spotlight']);

export function setBafResolutionLayout(layout, coinPosition = 'center') {
  if (!active) return;
  active.overlay.dataset.layout = BAF_REVEAL_LAYOUTS.includes(layout) ? layout : 'spotlight';
  active.overlay.dataset.coinPosition = coinPosition === 'corner' ? 'corner' : 'center';
}

function _shortAddress(address) {
  return address ? `${address.slice(0, 6)}…${address.slice(-4)}` : '—';
}

function _prizeLabel(prize) {
  if (prize.kind === 'eth') return `${_formatEth(prize.amount, 4)} ETH`;
  if (prize.kind === 'tickets') return `${prize.amount} TKT${prize.level == null ? '' : ` · L${prize.level}`}`;
  return formatBafWhalePassHalves(prize.amount);
}

function _playerRow(player, snapshot, top = false) {
  const row = document.createElement('li');
  row.className = 'baf-res__player';
  row.dataset.rank = player.rank;
  row.dataset.player = player.player;
  const own = player.player === snapshot.player.address;
  row.classList.toggle('is-you', own);
  if (top && player.rank === 2) row.classList.add('is-out');
  const rank = document.createElement('b');
  rank.className = 'baf-res__rank';
  rank.textContent = String(player.rank).padStart(2, '0');
  const identity = document.createElement('span');
  identity.className = 'baf-res__identity';
  identity.title = player.player;
  identity.textContent = _shortAddress(player.player);
  if (own) {
    const you = document.createElement('em');
    you.textContent = 'YOU';
    identity.appendChild(you);
  }
  const score = document.createElement('span');
  score.className = 'baf-res__score';
  score.textContent = formatBafResolutionScore(player.score);
  score.title = `${score.textContent} BAF score`;
  const prize = document.createElement('strong');
  prize.className = 'baf-res__prize';
  if (top) {
    prize.textContent = player.rank === 1 ? '10% OF POOL' : player.rank === 2 ? 'OUT' : '5% / FLIP';
  } else {
    prize.textContent = player.prizes == null ? 'PENDING' : player.prizes.length
      ? player.prizes.map(_prizeLabel).join(' + ') : '—';
    row.classList.toggle('is-winner', Boolean(player.prizes?.length));
    // Being sampled belongs in this board even if the player lost the comparison.
    row.classList.toggle('is-out', Array.isArray(player.prizes) && !player.prizes.length);
  }
  row.append(rank, identity, score, prize);
  return row;
}

function _paintLeaders(overlay, snapshot) {
  const list = overlay.querySelector('[data-bind="baf-leaders"]');
  for (const player of snapshot.topFour) list.appendChild(_playerRow(player, snapshot, true));
  if (!snapshot.topFour.length) {
    const empty = document.createElement('li');
    empty.className = 'baf-res__empty-leaders';
    empty.textContent = 'Leaderboard details are still syncing.';
    list.appendChild(empty);
  }
  const rotor = overlay.querySelector('[data-bind="baf-cut-coin"]');
  appendCoinFaces(rotor, {
    frontSrc: '/badges-circular/dice_02_3_blue.svg',
    backSrc: '/badges-circular/dice_03_4_purple.svg',
  });
}

function _paintComparisons(overlay, snapshot) {
  const grid = overlay.querySelector('[data-bind="baf-comparisons"]');
  const groups = snapshot.comparisons || [];
  overlay.querySelector('[data-bind="baf-group-count"]').textContent = groups.length
    ? `${groups.length} DRAW${groups.length === 1 ? '' : 'S'} WITH YOU` : 'YOUR WALLET ONLY';
  for (const group of groups) {
    const card = document.createElement('article');
    card.className = 'baf-res__comparison';
    card.setAttribute('aria-label', `Draw ${group.round}, four players ranked by BAF score`);
    const header = document.createElement('header');
    const number = document.createElement('b');
    number.textContent = `DRAW ${String(group.round).padStart(2, '0')}`;
    const result = document.createElement('span');
    const own = group.players.filter((row) => row.isPlayer);
    const won = own.some((row) => row.prizes?.length);
    result.textContent = won ? 'YOU WON' : own.every((row) => row.prizes != null) ? 'DRAWN IN' : 'PENDING';
    result.classList.toggle('is-win', won);
    header.append(number, result);
    const columns = document.createElement('div');
    columns.className = 'baf-res__columns';
    columns.innerHTML = '<span>PLAYER</span><span>BAF SCORE</span><span>PRIZE WON</span>';
    const list = document.createElement('ol');
    for (const player of group.players) list.appendChild(_playerRow(player, snapshot));
    card.append(header, columns, list);
    grid.appendChild(card);
  }
  const more = overlay.querySelector('[data-bind="baf-scroll-note"]');
  more.hidden = groups.length <= 10;
  more.textContent = `${groups.length} comparisons · scroll for more`;
}

function _showResults(overlay, snapshot) {
  const locked = overlay.querySelector('[data-bind="baf-locked"]');
  locked.hidden = true;
  const grid = overlay.querySelector('[data-bind="baf-comparisons"]');
  const message = overlay.querySelector('[data-bind="baf-empty"]');
  const groups = snapshot.comparisons || [];
  if (snapshot.gateWon && groups.length) {
    grid.hidden = false;
  } else {
    message.hidden = false;
    const title = document.createElement('h3');
    const copy = document.createElement('p');
    title.textContent = !snapshot.gateWon ? 'THE BAF DID NOT FIRE'
      : snapshot.comparisonsAvailable ? 'NO COMPARISONS THIS ROUND' : 'YOUR BAF RESULTS';
    copy.textContent = !snapshot.gateWon ? 'The pool stays in the futurepool. No draws ran.'
      : snapshot.comparisonsAvailable ? 'You weren’t sampled into a four-player draw this round.'
        : 'Four-player comparison details are not available for this round.';
    message.append(title, copy);
    if (snapshot.gateWon) {
      const hits = document.createElement('div');
      hits.className = 'baf-res__receipt-list';
      for (const hit of snapshot.player.prizeHits || []) {
        const prize = document.createElement('strong');
        prize.textContent = _prizeLabel(hit);
        hits.appendChild(prize);
      }
      message.appendChild(hits);
    }
  }
}

