function _paintPayout(overlay, snapshot) {
  const payout = overlay.querySelector('[data-bind="baf-payout"]');
  if (!payout) return;
  payout.textContent = '';
  payout.className = 'baf-res__payout';
  const heading = document.createElement('strong');
  const rewards = document.createElement('span');
  rewards.className = 'baf-res__reward-list';
  const addReward = (label, kind, icon = null) => {
    const reward = document.createElement('b');
    reward.className = 'baf-res__reward';
    reward.dataset.kind = kind;
    if (icon) {
      const image = document.createElement('img');
      image.src = icon;
      image.alt = '';
      reward.appendChild(image);
    }
    const copy = document.createElement('span');
    copy.textContent = label;
    reward.appendChild(copy);
    rewards.appendChild(reward);
  };

  if (!snapshot.gateWon) {
    payout.classList.add('is-loss');
    heading.textContent = 'BAF LOSS';
    rewards.classList.add('is-summary');
    rewards.textContent = _big(snapshot.player.consolation) > 0n
      ? `${formatBafResolutionScore(snapshot.player.consolation)} WWXRP CONSOLATION`
      : 'NO DRAW · POOL STAYS IN THE FUTUREPOOL';
  } else if (snapshot.player.wonAny) {
    payout.classList.add('is-win');
    heading.textContent = 'YOUR BAF RESULT';
    if (_big(snapshot.player.eth) > 0n) {
      addReward(
        `${_formatEth(snapshot.player.eth, 4)} ETH`,
        'eth',
        '/badges-circular/crypto_06_ethereum_green.svg',
      );
    }
    if (_big(snapshot.player.tickets) > 0n) {
      addReward(
        `${snapshot.player.tickets} TICKET${_big(snapshot.player.tickets) === 1n ? '' : 'S'}`,
        'tickets',
        '/whitepaper/flame-center.svg',
      );
    }
    if (_big(snapshot.player.whalePassHalves) > 0n) {
      addReward(formatBafWhalePassHalves(snapshot.player.whalePassHalves), 'whale-pass', '/app/assets/baf-mark.svg');
    }
    if (!rewards.childElementCount && snapshot.player.leaderSlicePct > 0) {
      addReward(`${snapshot.player.leaderSlicePct}% LEADER PRIZE · SYNCING`, 'leader');
    }
  } else {
    payout.classList.add('is-miss');
    heading.textContent = 'NO BAF PAYOUT';
    rewards.classList.add('is-summary');
    rewards.textContent = [_rankLabel(snapshot.player.rank), `${formatBafResolutionScore(snapshot.player.score)} SCORE`].filter(Boolean).join(' · ');
  }
  payout.appendChild(heading);
  payout.appendChild(rewards);
}


function _settleLeaders(overlay, snapshot, cutComplete = false) {
  for (const row of overlay.querySelectorAll('[data-bind="baf-leaders"] .baf-res__player')) {
    const rank = Number(row.dataset.rank);
    const prize = row.querySelector('.baf-res__prize');
    if (!snapshot.gateWon) { prize.textContent = 'NO DRAW'; continue; }
    if (rank === 1) { row.classList.add('is-winner'); prize.textContent = '10% OF POOL'; }
    if (rank < 3) continue;
    if (!snapshot.cutKnown) { prize.textContent = 'PENDING'; continue; }
    if (!cutComplete) continue;
    const won = rank === snapshot.survivorRank;
    row.classList.add(won ? 'is-winner' : 'is-out');
    prize.textContent = won ? '5% OF POOL' : 'OUT';
  }
}

function _finishCeremony(overlay, snapshot) {
  overlay.querySelector('[data-bind="baf-shell"]').dataset.stage = 'complete';
  const wheel = overlay.querySelector('[data-bind="baf-draw-wheel"]');
  wheel.classList.remove('is-spinning');
  wheel.classList.add(snapshot.gateWon ? 'is-settled' : 'is-void');
  const drawState = overlay.querySelector('[data-bind="baf-draw-state"]');
  const winner = snapshot.draw?.winner;
  drawState.textContent = !snapshot.gateWon ? 'NO DRAW'
    : winner && winner === snapshot.player.address ? 'YOU WON THE DRAW'
      : winner ? `${_shortAddress(winner)} WINS`
        : snapshot.draw?.winnerKnown ? 'NO DRAW ENTRIES' : 'DRAW RESULT UNAVAILABLE';
  if (winner && snapshot.gateWon) drawState.title = winner;
  _paintPayout(overlay, snapshot);
  const done = overlay.querySelector('[data-bind="baf-done"]');
  done.hidden = false;
  // Only hand focus forward if it was on the now-disabled reveal button.
  if (document.activeElement === overlay.querySelector('[data-bind="baf-flip"]')) {
    try { done.focus({ preventScroll: true }); } catch (_e) {}
  }
  document.dispatchEvent(new CustomEvent('baf:revealed', {
    detail: { level: snapshot.level, won: snapshot.gateWon, prizeHits: snapshot.player.prizeHits?.length || 0 },
  }));
}

function _runCeremony(overlay, snapshot) {
  const shell = overlay.querySelector('[data-bind="baf-shell"]');
  if (shell.dataset.stage !== 'coin') return;
  const button = overlay.querySelector('[data-bind="baf-flip"]');
  const rotor = overlay.querySelector('[data-bind="baf-coin"]');
  const result = overlay.querySelector('[data-bind="baf-gate-result"]');
  const timing = _motionReduced() ? REDUCED_TIMING : NORMAL_TIMING;
  button.disabled = true;
  shell.dataset.stage = 'coin-flip';
  rotor.classList.add('is-flipping', snapshot.gateWon ? 'is-win' : 'is-loss');
  result.textContent = 'FLIPPING';
  _sound(warmupCoinflipSfx);
  _sound(sfxCoinflipStart);
  _schedule(() => _sound(() => sfxCoinflipWhoosh(0.82)), Math.floor(timing.flip * 0.46));
  _schedule(() => {
    overlay.dataset.gate = snapshot.gateWon ? 'win' : 'loss';
    result.textContent = snapshot.gateWon ? 'BAF FIRES' : 'BAF LOSS';
    button.setAttribute('aria-label', snapshot.gateWon ? 'BAF flip won' : 'BAF flip lost');
    shell.dataset.stage = 'results';
    _sound(() => sfxCoinflipLand(snapshot.gateWon));
    if (snapshot.gateWon) _paintComparisons(overlay, snapshot);
    _showResults(overlay, snapshot);
    _settleLeaders(overlay, snapshot);
    const cut = overlay.querySelector('[data-bind="baf-cut"]');
    const cutResult = overlay.querySelector('[data-bind="baf-cut-result"]');
    if (snapshot.gateWon) {
      const wheel = overlay.querySelector('[data-bind="baf-draw-wheel"]');
      wheel?.classList.add('is-spinning');
      if (snapshot.cutKnown) {
        cut.classList.add('is-flipping');
        cut.dataset.survivor = snapshot.survivorRank;
        cutResult.textContent = 'FLIPPING';
        cut.setAttribute('aria-label', 'Flipping between rank 3 and rank 4');
      } else {
        cutResult.textContent = 'PENDING';
        cut.setAttribute('aria-label', 'Rank 3 versus rank 4 result pending');
      }
    } else {
      cutResult.textContent = 'NO FLIP';
      cut.setAttribute('aria-label', 'No rank 3 versus rank 4 flip; BAF lost');
    }
    _schedule(() => {
      if (snapshot.gateWon && snapshot.cutKnown) {
        _settleLeaders(overlay, snapshot, true);
        cutResult.textContent = `#${snapshot.survivorRank} WINS`;
        cut.setAttribute('aria-label', `Rank ${snapshot.survivorRank} wins; rank ${snapshot.eliminatedCutRank} is out`);
      }
      _finishCeremony(overlay, snapshot);
    }, timing.cut);
  }, timing.flip);
}

export async function openBafResolution({
  level,
  player,
  consolation = 0,
  snapshot = null,
  playerOutcome = null,
  history = null,
  layout = 'spotlight',
  coinPosition = 'center',
  preview = false,
} = {}) {
  if (typeof document === 'undefined' || !document.body) return false;
  const seq = ++openSeq;
  _destroyActive();

  // The normal Community Coinflip uses the same transition moment. Park that
  // background coin while the player-specific fullscreen data loads so it
  // cannot preview or compete with the BAF gate ceremony.
  document.body.classList.add('baf-resolution-pending');
  let resolved;
  try {
    resolved = snapshot || await loadBafResolutionSnapshot({
      level,
      player,
      consolation,
      playerOutcome,
      history,
    });
  } catch (error) {
    if (seq === openSeq) document.body.classList.remove('baf-resolution-pending');
    throw error;
  }
  if (seq !== openSeq) return false;

  const overlay = document.createElement('section');
  overlay.className = 'baf-res-modal';
  overlay.setAttribute('role', 'dialog');
  overlay.setAttribute('aria-modal', 'true');
  overlay.setAttribute('aria-label', `Level ${Number(level)} Big Ass Flip resolution`);
  const previousFocus = document.activeElement;
  const onKeydown = (event) => {
    if (event?.key === 'Escape') _clearActive();
    if (event?.key !== 'Tab' || preview) return;
    const focusable = [...overlay.querySelectorAll('button:not([disabled]), [tabindex="0"]')]
      .filter((node) => node.getClientRects().length && !node.closest('[hidden]'));
    const first = focusable[0];
    const last = focusable.at(-1);
    if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); }
    else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); }
  };
  active = { overlay, timers: new Set(), onKeydown, previousFocus };
  setBafResolutionLayout(layout, coinPosition);
  if (preview) overlay.setAttribute('aria-modal', 'false');

  try {
    _renderSnapshot(overlay, resolved);
    if (seq !== openSeq || active?.overlay !== overlay) return false;
    document.addEventListener('keydown', onKeydown);
    document.body.appendChild(overlay);
    document.body.classList.remove('baf-resolution-pending');
    document.body.classList.add('baf-resolution-open');
    try { overlay.querySelector('[data-bind="baf-flip"]')?.focus({ preventScroll: true }); } catch (_e) {}
    return true;
  } catch (error) {
    if (active?.overlay === overlay) _destroyActive();
    throw error;
  }
}
